// Real docs/entities.tide, regenerated by build.py. Including its C lets this
// test use the game's own wire encoders, without hand-copying its wire schema.
#include "entities.c"

#define CHECK(x) do { if (!(x)) { fprintf(stderr, "failed %s:%d: %s\n", __FILE__, __LINE__, #x); exit(1); } } while (0)

static uint64_t digest;
static uint32_t sequence;

static void equal(const tide_world *a, const tide_world *b)
{
    const uint64_t hash = tide_world_hash(a);
    CHECK(hash == tide_world_hash(b));
    CHECK(a->arch0_Ball_Health.count == b->arch0_Ball_Health.count);
    for (uint32_t r = 0; r < a->arch0_Ball_Health.count; ++r) {
        const tide_entity ea = TIDE_ENTITY_AT(a, arch0_Ball_Health, r);
        const tide_entity eb = TIDE_ENTITY_AT(b, arch0_Ball_Health, r);
        CHECK(tide_entity_equal(ea, eb));
        const Health ha = tide_get_Health(a, ea), hb = tide_get_Health(b, eb);
        CHECK(ha.value == hb.value);
        CHECK(tide_has_Poisoned(a, ea) == tide_has_Poisoned(b, eb));
    }
    const uint32_t size = tide_world_pack(a, NULL, 0);
    CHECK(size == tide_world_pack(b, NULL, 0));
    uint8_t *pa = malloc(size), *pb = malloc(size);
    CHECK(pa && pb);
    CHECK(tide_world_pack(a, pa, size) == size);
    CHECK(tide_world_pack(b, pb, size) == size);
    CHECK(!memcmp(pa, pb, size));
    tide_world restored = {0};
    CHECK(tide_world_unpack(&restored, pb, size));
    CHECK(tide_world_hash(&restored) == hash);
    tide_world_free(&restored);
    free(pa); free(pb);
    digest = digest * UINT64_C(6364136223846793005) + hash;
}

static void commands(tide_world *a, tide_world *b, uint32_t tick)
{
    uint8_t bytes[64];
    uint32_t size;
    if (tick % 7u == 0u || a->arch0_Ball_Health.count < 3u) {
        const Drop drop = {.at = {(float)(tick % 5u) * 0.3f, (float)(tick % 3u) * 0.2f}};
        size = tide_write_command_Drop((tide_entity){0}, drop, bytes, sizeof bytes);
    } else {
        const uint32_t row = (tick * 17u) % a->arch0_Ball_Health.count;
        const tide_entity e = TIDE_ENTITY_AT(a, arch0_Ball_Health, row);
        if (tick % 11u == 0u)
            size = tide_write_command_Cure(e, (Cure){0}, bytes, sizeof bytes);
        else
            size = tide_write_command_Poison(e, (Poison){0}, bytes, sizeof bytes);
    }
    CHECK(size);
    ++sequence;
    const tide_player_id sender = tide_player_from_index(0);
    CHECK(tide_game_api.command(a, sender, 0, sequence, bytes, size));
    CHECK(tide_game_api.command(b, sender, 0, sequence, bytes, size));
}

static void view(const tide_world *w, const tide_world *previous, tide_local *local,
                 tide_draw_list *draw, tide_gui *gui)
{
    tide_devices devices = {0};
    tide_draw_reset(draw);
    tide_gui_begin(gui, &devices, (tide_float2){640, 480}, NULL);
    tide_frame(w, previous, 0.5f, w, previous, 0.5f, local, draw, gui);
    tide_gui_end(gui, draw);
}

static void equal_draw(const tide_draw_list *a, const tide_draw_list *b)
{
#define SAME(field, count) do { CHECK(a->count == b->count); if (a->count) CHECK(!memcmp(a->field, b->field, a->count * sizeof *a->field)); } while (0)
    SAME(commands, count); SAME(text, text_used); SAME(plains, plain_count);
    SAME(vertices, vertex_count); SAME(indices, index_count); SAME(quads, quad_count);
    SAME(cameras, camera_count); SAME(clips, clip_count); SAME(turns, turn_count);
#undef SAME
}

int main(void)
{
    CHECK(!getenv("TIDE_PACKED_MODE"));
    tide_world a = {0}, b = {0}, old_a = {0}, old_b = {0};
    tide_local la = {0}, lb = {0};
    tide_draw_list da = {0}, db = {0};
    tide_gui *ga = calloc(1, sizeof *ga), *gb = calloc(1, sizeof *gb);
    CHECK(ga && gb);
    tide_packed_rows_mode = 0;
    tide_world_init(&a, 1.0f / 30.0f);
    tide_world_copy(&b, &a);
    tide_local_init(&la); tide_local_init(&lb);
    uint32_t removed = 0;
    for (uint32_t tick = 0; tick < 360; ++tick) {
        tide_world_copy(&old_a, &a); tide_world_copy(&old_b, &b);
        commands(&a, &b, tick);
        const uint32_t before = a.arch0_Ball_Health.count;
        tide_packed_rows_mode = 0; tide_world_tick(&a);
        tide_packed_rows_mode = 2; tide_world_tick(&b);
        CHECK(!a.arch0_Ball_Health.mapping && !b.arch0_Ball_Health.mapping);
        CHECK(!a.arch1_Main.mapping && !b.arch1_Main.mapping);
        if (a.arch0_Ball_Health.count < before) removed += before - a.arch0_Ball_Health.count;
        equal(&a, &b); equal(&old_a, &old_b);
        uint32_t size = 0;
        uint8_t *delta = tide_world_pack_delta(&b, &old_b, NULL, 0, &size);
        tide_world received = {0};
        CHECK(delta && tide_world_unpack_delta(&received, &old_a, delta, size));
        CHECK(tide_world_hash(&received) == tide_world_hash(&a));
        tide_world_free(&received); free(delta);
        view(&a, &old_a, &la, &da, ga); view(&b, &old_b, &lb, &db, gb);
        equal_draw(&da, &db);
        CHECK(la.Pointing.balls == lb.Pointing.balls && la.Pointing.poisoned == lb.Pointing.poisoned);
    }
    CHECK(removed > 0);
    CHECK(tide_packed_rows_passes > 0 && tide_packed_rows_count > 0);
    printf("PASS entities replay: 360 ticks, commands, IDs, membership, destruction=%u, hashes, raw/delta restores, snapshot views; passes=%llu rows=%llu digest=%llu\n",
           removed, (unsigned long long)tide_packed_rows_passes, (unsigned long long)tide_packed_rows_count, (unsigned long long)digest);
    tide_world_free(&a); tide_world_free(&b); tide_world_free(&old_a); tide_world_free(&old_b);
    tide_local_free(&la); tide_local_free(&lb);
    tide_draw_free(&da); tide_draw_free(&db); tide_draw_free(&ga->list); tide_draw_free(&gb->list);
    free(ga); free(gb);
    return 0;
}
